// Skywhale v6 — ai-excited-01 entry program (Node 22, stdlib only).
//
// Copies the pre-generated entry image (entry.png, next to this script)
// into the output directory the competition harness expects:
//   $MAKEFUN_OUTPUT_DIR, falling back to /output.
// The image itself is a static asset generated by the author in this
// session; this program only places it where the judge looks for it.
// It fails loudly if the source image is missing or the copy is short,
// so a broken entry can never pass silently.

import { copyFileSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
const src = join(here, "entry.png");
const dst = join(outDir, "entry.png");

const expected = statSync(src).size; // throws a clear ENOENT if missing
mkdirSync(outDir, { recursive: true });
copyFileSync(src, dst);

const actual = statSync(dst).size;
if (actual !== expected) {
  throw new Error(`copy incomplete: ${actual} of ${expected} bytes`);
}
console.log(`wrote ${dst} (${actual} bytes)`);
